      {"id":"lam-hipertrofia","t":"Láminas P1 · Hipertrofia cardíaca","q":"Observe la lámina y diga: órgano, proceso, alteraciones (descripción) y diagnóstico presuntivo.","img":"/mapas/img/laminario/lam-02.jpg","a":"Órgano: Corazón. Proceso: Adaptativo. Alteraciones: Cardiomiocitos hipertróficos; Anormalmente ramificados; Núcleos hipercromáticos y agrandados; Disposición irregular; Fibrosis cicatricial; Lipofucsina. Dx: Hipertrofia cardíaca.","x":"Lámina de la P1 (descripción de la profesora en la práctica).","b":[{"o":"Corazón","p":"Adaptación celular (Hipertrofia)","d":["Cardiomiocitos hipertróficos","Anormalmente ramificados","Núcleos hipercromáticos y agrandados","Disposición irregular","Fibrosis cicatricial","Lipofucsina"],"x":"Hipertrofia cardíaca"}]},
      {"id":"lam-hpb","t":"Láminas P1 · Hiperplasia prostática benigna","q":"Observe la lámina y diga: órgano, proceso, alteraciones (descripción) y diagnóstico presuntivo.","img":"/mapas/img/laminario/lam-24.jpg","a":"Órgano: Próstata. Proceso: Adaptativo / inflamatorio crónico. Alteraciones: Proliferación de glándulas benignas (aumento del número de células); Dilataciones glandulares; Invaginaciones papilares; Áreas quísticas con cuerpos amiláceos; Infiltrado inflamatorio crónico sobreagregado. Dx: Hiperplasia prostática benigna; prostatitis crónica.","x":"Lámina de la P1 (descripción de la profesora en la práctica).","b":[{"o":"Próstata","p":"Adaptación Celular (hiperplasia)","d":["Proliferación de glándulas benignas (aumento del número de células)","Dilataciones glandulares","Invaginaciones papilares","Áreas quísticas con cuerpos amiláceos","Infiltrado inflamatorio crónico sobreagregado"],"x":"Hiperplasia prostática benigna; prostatitis crónica"}]},
      {"id":"lam-barret","t":"Láminas P1 · Esófago de Barrett","q":"Observe la lámina y diga: órgano, proceso, alteraciones (descripción) y diagnóstico presuntivo.","img":"/mapas/img/laminario/lam-05.jpg","a":"Órgano: Esófago. Proceso: Adaptación celular (metaplasia). Alteraciones: Fragmentos de epitelio escamoso esofágico; Reemplazado por epitelio cilíndrico simple; Con microvellosidades; Células caliciformes. Dx: Esófago de Barrett.","x":"Lámina de la P1 (descripción de la profesora en la práctica).","b":[{"o":"Esófago","p":"Metaplasia intestinal","d":["Fragmentos de epitelio escamoso esofágico","Reemplazado por epitelio cilíndrico simple","Con microvellosidades","Células caliciformes"],"x":"Esófago de Barrett"}]},
      {"id":"lam-atrofia","t":"Láminas P1 · Atrofia testicular","q":"Observe la lámina y diga: órgano, proceso, alteraciones (descripción) y diagnóstico presuntivo.","img":"/mapas/img/laminario/lam-23.jpg","a":"Órgano: Testículo. Proceso: Adaptativo. Alteraciones: Desaparición del epitelio tubular; Túbulos pequeños y escleróticos; Áreas de fibrosis intersticial; Aumento de células de Leydig. Dx: Atrofia testicular.","x":"Lámina de la P1 (descripción de la profesora en la práctica).","b":[{"o":"Testículo","p":"Adaptación Celular (atrofia)","d":["Desaparición del epitelio tubular","Túbulos pequeños y escleróticos","Áreas de fibrosis intersticial","Aumento de células de Leydig"],"x":"Atrofia testicular"}]},
      {"id":"lam-bocio","t":"Láminas P1 · Bocio coloide multinodular","q":"Observe la lámina y diga: órgano, proceso, alteraciones (descripción) y diagnóstico presuntivo.","img":"https://drive.google.com/thumbnail?id=13MqqzQHnLrHwrdkyKca-RN2bfs8lh0aV&sz=w1000","a":"Órgano: Glándula tiroides. Proceso: Adaptativo. Alteraciones: Folículos dilatados de tamaño variable; Epitelio aplanado en sectores; Hiperplásico en otros sectores; Áreas de hemorragia. Dx: Bocio coloide multinodular.","x":"Lámina de la P1 (descripción de la profesora en la práctica).","b":[{"o":"Tiroides","p":"Adaptación celular (hiperplasia)","d":["Folículos dilatados de tamaño variable","Epitelio aplanado en sectores","Hiperplásico en otros sectores","Áreas de hemorragia"],"x":"Bocio coloide multinodular"}]}
